from pathlib import Path
import hashlib,json,subprocess,time
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).resolve().parent
texts=['0.1','1.0000000596046447753906250000000000000001','-1.0000000596046447753906250000000000000001','1.0000000596046447753906249999999999999999','1208925891672223212634113','-1208925891672223212634113','1E-1000','-1E-1000','1E+1000','0E+2147483648','1E+2147483648','-1E-2147483647','100E+2147483648']
source='(assert (= "1.12.6" (clojure-version)))\n'+''.join('(let [text '+json.dumps(x)+' value (java.math.BigDecimal. text) f (.floatValue value)] (println (str "[" (pr-str text) "," (pr-str (format "%08x" (Float/floatToRawIntBits f))) "," (pr-str (format "%016x" (Double/doubleToRawLongBits (double f)))) "]")))\n' for x in texts)
path=OUT/'float-fields-oracle.clj';path.write_text(source);prior=json.loads((ROOT/'results/m12-wide-wit/oracle-command.json').read_text());command=prior['command'][:-1]+[str(path)];started=time.time();p=subprocess.run(command,cwd=ROOT,capture_output=True,text=True);(OUT/'float-fields-oracle.log').write_text(p.stdout+p.stderr);(OUT/'float-fields-oracle-command.json').write_text(json.dumps({'command':command,'exit_code':p.returncode,'seconds':time.time()-started,'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'jars':{p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in prior['jars']}},indent=2)+'\n');assert p.returncode==0,p.stderr
rows=[json.loads(x) for x in p.stdout.splitlines()];assert len(rows)==len(texts);(OUT/'float-fields-cases.json').write_text(json.dumps([dict(text=x[0],f32_bits=x[1],f64_bits=x[2]) for x in rows],indent=2)+'\n')
